function samplePoll(s){const ranked=s.voters.map((v,i)=>({i,key:-Math.log(Math.max(.00001,rand(s.seed,100+s.day,i)))/(0.35+v.familiar*.9+v.support*.6)})).sort((a,b)=>a.key-b.key).slice(0,36);let yes=0;for(const {i}of ranked)if(rand(s.seed,200+s.day,i)<s.voters[i].support)yes++;return{day:s.day,n:36,yes,percent:Math.round(yes/36*100),range:12,source:'市場自願回覆的虛構樣本'};}
