if(id===1){s.platform='process';s.promises.push({id:'rent',kind:'bounded',text:'改善現有申請流程，暫不擴大補助',status:'kept'});s.impact++;adjust(s,{yun:-5});influence(s,v=>.022*(.5-v.urgency)+.005*v.precision);result='阿芸很失望，因為流程變好不一定能解決眼前的缺口。她仍聽完你的限制與理由。不同意一個人的主張，不等於全城都會離開。';reactions={yun:'「這個答案幫不到我眼前全部的困難。不過，我知道你沒有假答應。」'};}
